for record in catalogue:
    folder = Path(root) / record["id"]
    archive.write(folder / "manifest.json", record["id"] + "/manifest.json")
    if record["pinned"] or record["delivery"] in {"queued", "transferring"}:
        for name in (record["filename"], "cover.svg"):
            if (folder / name).is_file():
                archive.write(folder / name, record["id"] + "/" + name)

    elif command["kind"] == "upload":
        data = self.api(f"/v1/kobo/uploads/{identity}", binary=True)
        if digest(data) != command["sha256"]:
            raise ValueError("La subida no coincide con el archivo enviado.")
        if target.exists():
            if digest(target.read_bytes()) != command["sha256"]:
                raise ValueError("Ya hay en el Kobo otro libro con ese nombre. Cámbiale el nombre y vuelve a enviarlo.")
        else:
            partial = mount / (".margen-" + identity + ".partial")
            with partial.open("wb") as stream:
                stream.write(data)
                stream.flush()
                os.fsync(stream.fileno())
            if digest(partial.read_bytes()) != command["sha256"]:
                partial.unlink(missing_ok=True)
                raise ValueError("La copia USB no coincide; queda pendiente.")
            target.parent.mkdir(parents=True, exist_ok=True)
            partial.rename(target)
    else:
        raise ValueError("Orden desconocida.")
except ValueError as error:
    self.api(f"/v1/kobo/commands/{identity}/done", {**receipt, "ok": False, "message": str(error)[:500]})

existing = db.execute("SELECT * FROM kobo_commands WHERE state IN ('pending','executing') AND path=?", (path,)).fetchone()
if existing:
    if existing["kind"] == "remove":
        return row(existing)
    raise ValueError("Ese libro tiene una subida pendiente. Cancélala en su lugar.")

def listing(root):
    with database(root) as db:
        return [row(r) for r in db.execute("SELECT * FROM kobo_commands ORDER BY created_at DESC LIMIT 100")]

export function bookStatus(book: KoboBook, overview: KoboOverview): { text: string; removable: boolean } {
  const commands = overview.commands.filter(c => c.kind === "remove" && c.path === book.path && book.path);
  if (commands.some(c => ["pending", "executing"].includes(c.state))) return { text: "Se quitará en la próxima conexión", removable: false };

def illustrate(brief):
    nonlocal done
    if cancelled():
        raise Cancelled()
    job = ArtworkRequest(title=plan.title, visual=brief, sources=[notes[i] for i in brief.source_ids])
    prompt = image_prompt(job)
    digest = hashlib.sha256(prompt.encode()).hexdigest()
    cached = cache_dir / (digest + ".jpg")
    reused = cached.exists()
    if reused:
        encoded = {"data": base64.b64encode(cached.read_bytes()).decode(), "media_type": "image/jpeg"}
    elif provider == "codex-cli":
        encoded = codex_artwork(job)

def codex_artwork(request: ArtworkRequest):
    executable = os.getenv("CODEX_BIN") or shutil.which("codex")
    if not executable:
        raise ValueError("No se encuentra Codex para generar las ilustraciones.")
    if not SLOTS.acquire(timeout=480):
        raise ValueError("Codex está preparando otra edición. Espera a que termine.")
    try:
        env = dict(os.environ)
        for key in ["OPENAI_API_KEY", "CODEX_API_KEY", "OPENAI_BASE_URL"]:
            env.pop(key, None)
        login = subprocess.run([executable, "login", "status"], text=True, capture_output=True, timeout=15, env=env)
        if login.returncode or "using ChatGPT" not in login.stdout + login.stderr:
            raise ValueError("La generación visual requiere la sesión de ChatGPT en Codex.")
        with tempfile.TemporaryDirectory(prefix="margen-artwork-") as temp:
            workdir = Path(temp)

if (!book.present) return { text: "El archivo ya no está en el Kobo", removable: false };
const reading = book.percent ? `${book.percent} % leído` : book.last_read ? "Empezado" : "Sin abrir";
return { text: reading, removable: !!book.path };

